CREATE TABLE IF NOT EXISTS "system_config" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "system_name" VARCHAR(128) NOT NULL DEFAULT 'V3 Admin',
  "system_description" VARCHAR(500) NOT NULL DEFAULT '',
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO "system_config" ("id", "system_name", "system_description")
SELECT 1, 'V3 Admin', ''
WHERE NOT EXISTS (SELECT 1 FROM "system_config" WHERE "id" = 1);

COMMENT ON TABLE "system_config" IS '系统基础配置表';
COMMENT ON COLUMN "system_config"."id" IS '配置主键，固定为1';
COMMENT ON COLUMN "system_config"."system_name" IS '系统名称';
COMMENT ON COLUMN "system_config"."system_description" IS '系统描述';
COMMENT ON COLUMN "system_config"."created_at" IS '创建时间';
COMMENT ON COLUMN "system_config"."updated_at" IS '更新时间';

-- +goose Down
DROP TABLE IF EXISTS "system_config";
